<?php
namespace qqworld_collector\module\pseudo_original; use qqworld_collector\lib; class rewrite_title extends lib { var $log_id = 'pseudo-original'; public function init() { add_action( 'wp_insert_post', array($this, 'rewrite_title'), 10, 3 ); } public function rewrite_title($post_ID, $post, $update) { if (!$this->options->qc_pseudo_original_rewrite_title_enabled) return; if ($post->post_status != 'publish') return; $post_title = $this->do_rewrite_title($post->post_title); if ($post_title != $post->post_title) { wp_update_post(array( 'ID' => $post_ID, 'post_title' => $post_title )); } } public function do_rewrite_title($post_title) { switch ($this->options->qc_pseudo_original_rewrite_title_api) { case '5118': $host = "http://apis.5118.com"; $path = "/wyc/title"; $method = "POST"; $headers = array(); array_push($headers, "Authorization:" . $this->options->qc_pseudo_original_rewrite_title_5118_apikey); array_push($headers, "Content-Type".":"."application/x-www-form-urlencoded; charset=UTF-8"); $bodys = "txt={$post_title}"; $url = $host . $path; $curl = curl_init(); curl_setopt($curl, CURLOPT_CUSTOMREQUEST, $method); curl_setopt($curl, CURLOPT_URL, $url); curl_setopt($curl, CURLOPT_HTTPHEADER, $headers); curl_setopt($curl, CURLOPT_FAILONERROR, false); curl_setopt($curl, CURLOPT_RETURNTRANSFER, true); curl_setopt($curl, CURLOPT_HEADER, false); if (1 == strpos("$".$host, "https://")) { curl_setopt($curl, CURLOPT_SSL_VERIFYPEER, false); curl_setopt($curl, CURLOPT_SSL_VERIFYHOST, false); } curl_setopt($curl, CURLOPT_POSTFIELDS, $bodys); $results = curl_exec($curl); curl_close($curl); $results = json_decode($results, true); if ($results && !$results['errcode']) { $post_title = $results['data']; } else { do_action( 'qqworld-collector-log', $this->log_id, 'Rewrite Title 5118 failed $results:', print_r($results, true) ); } break; } return $post_title; } } ?>